import type { Metadata } from "next";
import { Inter, Outfit } from "next/font/google";
import "@/styles/globals.css";
import SmoothScroll from "@/components/layout/SmoothScroll";
import Navbar from "@/components/layout/Navbar";
import Footer from "@/components/layout/Footer";
import CustomCursor from "@/components/layout/CustomCursor";
import CookieConsent from "@/components/layout/CookieConsent";
import { cn } from "@/lib/utils";

const inter = Inter({ subsets: ["latin"], variable: "--font-inter" });
const outfit = Outfit({ subsets: ["latin"], variable: "--font-outfit" });

export const metadata: Metadata = {
  title: "Webkaro | Engineering Scalable Digital Experiences",
  description: "Webkaro is a community-driven development collective delivering high-performance, scalable websites and web applications for startups, founders, and enterprises.",
  keywords: ["Next.js development agency", "Web development company India", "SaaS MVP development", "Full-stack web agency"],
  openGraph: {
    title: "Webkaro | Engineering Scalable Digital Experiences",
    description: "High-performance websites and web applications for the modern web.",
    url: "https://webkaro.com",
    siteName: "Webkaro",
    locale: "en_US",
    type: "website",
  },
  twitter: {
    card: "summary_large_image",
    title: "Webkaro",
    description: "Engineering Scalable Digital Experiences",
  },
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en" className="dark">
      <body
        className={cn(
          inter.variable,
          outfit.variable,
          "min-h-screen bg-background text-foreground font-sans antialiased"
        )}
      >
        <SmoothScroll>
          <CustomCursor />
          <Navbar />
          <main className="relative flex flex-col min-h-screen">
            {children}
          </main>
          <Footer />
          <CookieConsent />
        </SmoothScroll>
      </body>
    </html>
  );
}
