import Link from "next/link";
import { Mail, MapPin, Phone, Instagram, Twitter, Linkedin, Github } from "lucide-react";

const footerLinks = {
  QuickLinks: [
    { name: "Home", href: "/" },
    { name: "About", href: "/about" },
    { name: "Projects", href: "/projects" },
    { name: "Blogs", href: "/blogs" },
    { name: "Contact", href: "/contact" },
  ],
  Services: [
    { name: "Web Development", href: "/services#web-development" },
    { name: "UI/UX Design", href: "/services#ui-ux" },
    { name: "SaaS MVP", href: "/services#saas-mvp" },
    { name: "API Integration", href: "/services#api-integration" },
  ],
  Legal: [
    { name: "Privacy Policy", href: "/privacy-policy" },
    { name: "Terms of Service", href: "/terms" },
    { name: "Compliance", href: "/compliance" },
  ],
};

export default function Footer() {
  return (
    <footer className="relative bg-background pt-32 pb-12 overflow-hidden border-t border-border/40">
      {/* Background Glow */}
      <div className="absolute bottom-0 left-1/2 -translate-x-1/2 w-[600px] h-[300px] bg-primary/10 blur-[120px] rounded-full pointer-events-none" />

      <div className="max-w-7xl mx-auto px-6 relative z-10">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-12 lg:gap-8">
          {/* Brand Column */}
          <div className="space-y-6">
            <Link href="/" className="flex items-center space-x-2">
              <div className="w-8 h-8 bg-gradient-to-br from-primary to-accent rounded-lg flex items-center justify-center font-bold text-white">
                W
              </div>
              <span className="text-xl font-bold tracking-tight text-white font-outfit">
                Webkaro
              </span>
            </Link>
            <p className="text-foreground/60 text-sm leading-relaxed max-w-xs">
              Engineering scalable digital experiences for startups and enterprises. We build high-performance web applications that drive growth.
            </p>
            <div className="flex space-x-4">
              <Link href="#" className="p-2 bg-muted rounded-lg hover:text-primary transition-colors">
                <Twitter className="w-5 h-5" />
              </Link>
              <Link href="#" className="p-2 bg-muted rounded-lg hover:text-primary transition-colors">
                <Linkedin className="w-5 h-5" />
              </Link>
              <Link href="#" className="p-2 bg-muted rounded-lg hover:text-primary transition-colors">
                <Instagram className="w-5 h-5" />
              </Link>
            </div>
          </div>

          {/* Links Columns */}
          <div>
            <h4 className="text-white font-semibold mb-6">Quick Links</h4>
            <ul className="space-y-4">
              {footerLinks.QuickLinks.map((link) => (
                <li key={link.name}>
                  <Link href={link.href} className="text-sm text-foreground/60 hover:text-primary transition-colors">
                    {link.name}
                  </Link>
                </li>
              ))}
            </ul>
          </div>

          <div>
            <h4 className="text-white font-semibold mb-6">Services</h4>
            <ul className="space-y-4">
              {footerLinks.Services.map((link) => (
                <li key={link.name}>
                  <Link href={link.href} className="text-sm text-foreground/60 hover:text-primary transition-colors">
                    {link.name}
                  </Link>
                </li>
              ))}
            </ul>
          </div>

          {/* Contact Column */}
          <div className="space-y-6">
            <h4 className="text-white font-semibold mb-6">Get in Touch</h4>
            <div className="space-y-4">
              <div className="flex items-start space-x-3 text-sm text-foreground/60">
                <Mail className="w-5 h-5 text-primary shrink-0" />
                <span>hello@webkaro.com</span>
              </div>
              <div className="flex items-start space-x-3 text-sm text-foreground/60">
                <Phone className="w-5 h-5 text-primary shrink-0" />
                <span>+91 91407 68903</span>
              </div>
              <div className="flex items-start space-x-3 text-sm text-foreground/60">
                <MapPin className="w-5 h-5 text-primary shrink-0" />
                <span>Lucknow, Uttar Pradesh, India</span>
              </div>
            </div>
          </div>
        </div>

        <div className="mt-20 pt-8 border-t border-border/40 flex flex-col md:flex-row items-center justify-between gap-4">
          <p className="text-xs text-foreground/50">
            © {new Date().getFullYear()} Webkaro. All rights reserved. Registered in India.
          </p>
          <div className="flex space-x-6">
            {footerLinks.Legal.map((link) => (
              <Link key={link.name} href={link.href} className="text-xs text-foreground/50 hover:text-primary transition-colors">
                {link.name}
              </Link>
            ))}
          </div>
        </div>
      </div>
    </footer>
  );
}
